// CCAR-P practice papers: original items for internal domain P2 (official D1, Solution Design & Architecture).
// Format and provenance rules: see ccar-p.papers-items-p1.js.
(() => {
  const raw = window.CCARP_PAPER_ITEMS_RAW = window.CCARP_PAPER_ITEMS_RAW || {};
  raw.P2 = [
    // D1.1 Translate business problems into Claude-based AI solutions
    {t:"s",o:"D1.1",q:"A hospital network asks for 'AI to reduce insurance claim denials.' Denials cost it about $40 million a year, but no one has broken down why claims are denied. What should the architect do first?",
      c:["Analyze why claims are denied, find the language-heavy causes, and set a measurable target","Correct. Understanding which denial causes AI can address, and agreeing a target, turns a vague goal into a solvable problem."],
      x:[["Choose the most capable model so the solution can handle any kind of denial that comes up","Model choice comes after the problem is understood; capability alone does not say what to build."],
         ["Build a staff chatbot that answers billing questions, since that is the fastest thing to show","A quick demo may not touch the causes of denials and sets the wrong expectations."],
         ["Automate the full appeals process end to end so every denied claim is resubmitted by AI","Automating every appeal skips the analysis of causes and adds risk without a clear target."]],
      w:"Translating a business problem starts with decomposing it: find where the value is lost, which parts involve the language and judgment work Claude is good at, and what measurable outcome defines success."},
    {t:"s",o:"D1.1",q:"A retailer wants to 'use AI to speed up returns.' Discovery shows 70% of the delay comes from a warehouse scanning backlog, and 15% from agents reading long customer emails. What should the architect recommend?",
      c:["Tell the sponsor the main delay is a process issue, and scope AI to email triage where it fits","Correct. An honest framing points AI at the part of the problem it can solve and avoids promising a fix it cannot deliver."],
      x:[["Build an AI agent that manages the warehouse scanners so the whole delay is addressed at once","The scanning backlog is a physical and staffing problem; an agent does not add scanning capacity."],
         ["Proceed with a general returns chatbot, since any AI project will improve the overall speed","A chatbot that ignores the main bottleneck is unlikely to move the outcome the sponsor cares about."],
         ["Decline the project, because AI cannot help with a problem that is mostly operational","Declining outright misses the real, smaller opportunity in email handling."]],
      w:"Good solution framing separates the parts of a business problem that suit language models from those that need process, staffing or software changes, and sets expectations accordingly."},
    {t:"s",o:"D1.1",q:"An insurer's executive wants Claude to 'replace underwriters.' Time studies show underwriters spend about 60% of their day gathering and reading documents and 40% making risk decisions. Which framing is most likely to deliver value safely?",
      c:["Let Claude gather and summarize documents while underwriters decide; track cycle time","Correct. This targets the largest time sink while keeping accountable decisions with qualified people."],
      x:[["Have Claude make all underwriting decisions and route only declined applications to a human","Fully automating risk decisions is a large regulatory and accuracy leap that the time study does not justify."],
         ["Start by fine-tuning a model on past decisions so it can copy underwriters' judgment exactly","Copying past decisions can encode past errors and bias, and it skips the bigger document-handling opportunity."],
         ["Give underwriters a general chat assistant and let each person decide how to use it","Unstructured access rarely produces a measurable change in cycle time."]],
      w:"Business problems are often best solved by augmenting people on the time-consuming language work, with decisions kept where accountability lies, and with a clear metric such as cycle time."},
    {t:"s",o:"D1.1",q:"A company has five candidate AI use cases and budget for one pilot. Which one is the best first candidate?",
      c:["Triage of 30,000 inbound customer emails a month into categories, with historical labels available","Correct. High volume, language-heavy work, existing labeled data and a measurable outcome make this a strong pilot."],
      x:[["Fully automated approval of credit applications, replacing the current lending committee","High-impact automated decisions need far more evidence and controls than a first pilot can provide."],
         ["An assistant that writes the company's five-year strategy for the board, starting next quarter","The output is hard to evaluate, and the use case is low volume with unclear success criteria."],
         ["Predicting next year's demand for a brand-new product with no historical sales data yet","Without data, there is nothing to ground or evaluate the predictions against."]],
      w:"Strong first use cases are high volume, language-centric, measurable and low risk, with data available to build and evaluate the solution."},
    {t:"s",o:"D1.1",q:"A sponsor says the new contract assistant 'must never make a mistake.' How should the architect turn this into a workable requirement?",
      c:["Define acceptable error rates per error type, with human review where an error would be costly","Correct. Explicit tolerances by error type, plus review for high-impact cases, make the requirement testable and realistic."],
      x:[["Accept the requirement as written and choose the most capable model so errors do not happen","No model guarantees zero errors; accepting the requirement sets up the project to fail."],
         ["Ignore the statement, since sponsors often overstate their requirements early in a project","Ignoring it leaves a hidden expectation that will surface as a dispute later."],
         ["Promise zero errors in the pilot and revisit the requirement after the launch has gone well","Promising what cannot be delivered damages trust when the first error appears."]],
      w:"Business requirements must become measurable acceptance criteria. For language systems that means agreed error tolerances, segmented by consequence, and controls such as human review where errors are costly."},
    {t:"s",o:"D1.1",q:"A finance team wants Claude to reconcile 2 million ledger entries a month by matching amounts and dates across systems, and to explain the discrepancies it finds. What is the right solution shape?",
      c:["Match entries in code, then have Claude explain the discrepancies and suggest likely causes","Correct. Exact matching is a deterministic job; Claude adds value in explaining and investigating the exceptions."],
      x:[["Send every ledger entry to Claude and ask it to find the matches and explain any differences","Using a model for exact matching at this volume is costly, slower and less reliable than code."],
         ["Use Claude to write the matching rules once, then remove the AI component from the process","Generating rules can help, but dropping Claude loses the value of explaining exceptions."],
         ["Ask analysts to keep reconciling manually and use Claude only to format their final reports","This leaves the high-volume matching problem unsolved."]],
      w:"Part of translating a problem is deciding what not to give the model. Exact, high-volume computation belongs in code; Claude is best applied to interpretation and explanation."},
    {t:"m",o:"D1.1",q:"A contact center asks for 'AI to make agents more productive.' Which TWO steps best turn this into a solution plan?",
      c:[["Measure today's baseline for handle time, after-call work and resolution rate","Correct. A baseline is required to show any improvement and to size the opportunity."],
         ["Identify which parts of the agent's work are language-heavy, such as call summaries and knowledge lookups","Correct. This points the solution at the work where Claude is most likely to save time."]],
      x:[["Replace a share of the agents immediately to make the savings visible to leadership","Cutting staff before the solution is proven creates risk and does not define what to build."],
         ["Select the model with the best public benchmark score before talking to agents","Benchmarks do not reveal where this contact center's time is spent."],
         ["Build summaries, coaching, routing and forecasting all at once to maximize impact","Building everything at once makes it hard to measure what worked and delays value."]],
      w:"A solution plan needs a measured baseline and a clear view of which tasks suit the model, so the work is targeted and its impact can be shown."},
    {t:"c",o:"D1.1",q:"A business-intake board is screening requests. For each request, choose the approach that fits best. Options may be reused.",
      opts:["A Claude-based solution","Deterministic software or rules","Not ready yet: data or process work comes first"],
      rows:[["Summarize long customer emails into structured case notes",0,"Reading and summarizing unstructured text is a strong fit for Claude."],
            ["Calculate payroll tax withholding for each employee",1,"Exact, rule-defined calculations belong in deterministic software."],
            ["Predict which customers will cancel next quarter, when no history of cancellations has been recorded",2,"Without historical data there is nothing to build or evaluate a solution on."],
            ["Draft first-pass answers to RFP questions from an approved content library",0,"Grounded drafting from approved content suits Claude, with human review."],
            ["Require manager approval for every order over $10,000",1,"A fixed approval rule is simplest and most reliable as code."]],
      w:"Part of solution design is matching each problem to the right tool: Claude for language and judgment work, code for exact rules, and groundwork first when data or processes are missing."},

    // D1.2 Design end-to-end architectures (input → processing → output → feedback loops)
    {t:"s",o:"D1.2",q:"A knowledge assistant has been live for three months. Users click thumbs-down on about 8% of answers, but that feedback goes to a dashboard nobody acts on, and prompts have not changed since launch. What is missing from the architecture?",
      c:["A feedback loop that turns flagged answers into reviewed eval cases and fixes","Correct. Feedback only improves the system when it flows into evaluation, review and changes."],
      x:[["A larger model, since 8% negative feedback means the current one is not capable enough","Upgrading without analyzing the feedback may not fix the actual failure causes."],
         ["A second dashboard that breaks thumbs-down clicks down by hour and by department","More reporting without a path to action leaves the loop just as open."],
         ["Removing the thumbs-down button, because the feedback is not being used anyway","Removing feedback discards the most direct signal about real-world quality."]],
      w:"An end-to-end architecture includes a feedback stage: production signals are reviewed, added to evaluation sets and used to improve prompts, retrieval or models."},
    {t:"s",o:"D1.2",q:"An intake system receives scanned PDFs, forwarded emails and spreadsheets. Claude's extraction quality is poor mainly because some files arrive as unreadable images or in unexpected formats. Where should the architecture change?",
      c:["An ingestion stage that detects formats, converts and checks files, and rejects bad ones","Correct. Normalizing and validating inputs before processing removes a whole class of downstream failures."],
      x:[["Add instructions to the extraction prompt asking Claude to handle any file format it receives","Prompt instructions cannot recover text that the model never received in usable form."],
         ["Switch to a model with a larger context window so that whole files can be included","Context size does not help when the input is unreadable or malformed."],
         ["Ask the downstream team to correct extraction errors by hand after each batch completes","Manual correction downstream treats the symptom and does not scale."]],
      w:"End-to-end design includes the input stage. Format detection, conversion, OCR where needed and validation ensure the model receives usable content."},
    {t:"s",o:"D1.2",q:"Claude's output feeds an ERP system that rejects records with missing or mistyped fields. Today about 3% of records fail at import and are silently dropped. What output-stage design fixes this?",
      c:["Use schema-constrained outputs, validate before import, and send failures to a retry and review queue","Correct. Structured outputs plus validation and a dead-letter path make failures visible and recoverable."],
      x:[["Ask the model in the prompt to be especially careful with field names and data types","Instructions alone do not guarantee valid output or handle the failures that still occur."],
         ["Raise the model's temperature so that it tries a different format when one fails","Randomness makes output less predictable, not more valid."],
         ["Accept the 3% loss as normal for an AI system and report it in the monthly review","Silently dropping records is a data-integrity problem, not an acceptable cost."]],
      w:"The output stage needs a contract with downstream systems: constrained structure, validation and a defined path for records that still fail."},
    {t:"s",o:"D1.2",q:"A contract-drafting assistant produces clauses that lawyers edit before signing. Where should human review sit in the end-to-end flow?",
      c:["After drafting, before the contract system, with edits saved as feedback","Correct. Review before the system of record prevents errors from becoming binding, and captured edits improve future drafts."],
      x:[["After the contract is signed, as a quarterly audit of a sample of agreements","Reviewing after signing is too late to prevent binding errors."],
         ["Before drafting, by having lawyers approve each prompt the assistant will run","Approving prompts does not check the content of each generated clause."],
         ["Nowhere in the flow, since lawyers will notice any problems while negotiating","Relying on negotiation to catch errors is unreliable and unmeasured."]],
      w:"Human review belongs where it can stop errors before they reach a system of record or a customer, and the reviewers' corrections should feed back into evaluation and improvement."},
    {t:"m",o:"D1.2",q:"A team's design for an internal policy assistant shows only 'user question → Claude → answer.' Which TWO additions are most important to make it a complete end-to-end architecture?",
      c:[["An ingestion and retrieval path that keeps policy sources current and supplies them to the model","Correct. Grounding in current sources is the processing step that makes answers trustworthy."],
         ["A feedback and evaluation loop that captures problems and measures quality over time","Correct. Without feedback, quality cannot be tracked or improved after launch."]],
      x:[["A larger model, so the design can rely on what the model already knows about the policies","General model knowledge does not include the company's current policies."],
         ["A much longer system prompt that contains as many policy rules as possible","A static prompt goes stale and does not scale to a large, changing policy set."],
         ["Turning off logging to keep latency as low as possible for users","Removing logs removes the evidence needed for feedback and troubleshooting."]],
      w:"An end-to-end architecture covers inputs and sources, processing, outputs and the feedback loop. A bare model call covers only one of these."},
    {t:"x",o:"D1.2",q:"A design review checks the end-to-end architecture of a document-processing system. For each practice, mark whether it is appropriate.",
      rows:[["Validate and normalize inputs before they reach the model",true,"Yes. Clean inputs prevent avoidable processing failures."],
            ["Write model outputs straight into the system of record when the model says it is confident",false,"No. Model self-confidence is not a validation step."],
            ["Capture reviewer corrections and use them to extend the evaluation set",true,"Yes. Corrections are the most direct evidence of real-world failure."],
            ["Agree the output schema with the teams that consume the results",true,"Yes. An output contract prevents integration failures downstream."],
            ["Treat the feedback stage as optional once the system has launched",false,"No. Feedback is how a deployed system keeps improving and catches drift."]],
      w:"End-to-end designs need validated inputs, verified outputs with a clear contract, and a feedback loop that continues after launch."},

    // D1.3 Select appropriate architectural patterns (workflow, agentic, augmented LLM)
    {t:"s",o:"D1.3",q:"A support inbox receives three very different kinds of requests: billing disputes, technical outages and sales inquiries. Each needs different instructions, tools and tone. Which pattern fits best?",
      c:["Routing: classify each request first, then pass it to a handler specialized for that category","Correct. Routing lets each category get its own instructions and tools without one prompt trying to do everything."],
      x:[["One large prompt that contains the instructions and tools for all three categories together","A single prompt for very different tasks tends to perform worse on each of them."],
         ["An autonomous agent that decides its own steps for each email with access to every tool","Full autonomy is unnecessary when the categories and their handling are already known."],
         ["A multi-agent debate in which three agents discuss how each email should be handled","Debate adds cost and latency without a need for multiple perspectives."]],
      w:"Routing is a workflow pattern for inputs that fall into distinct categories. Classification first allows each category to have optimized handling."},
    {t:"s",o:"D1.3",q:"A marketing team needs product descriptions translated into German that follow a 40-term brand glossary and a tone guide. First drafts often miss glossary terms. Which pattern fits best?",
      c:["Evaluator-optimizer: draft, check against the glossary and tone guide, then revise","Correct. Clear evaluation criteria make an iterative critique-and-revise loop effective."],
      x:[["A single prompt with the glossary attached, accepting whatever the first draft produces","A single pass already misses glossary terms; nothing in this design catches or fixes them."],
         ["An autonomous agent with web access that decides how to research each translation","Open-ended research does not address the specific, checkable glossary requirement."],
         ["Parallel translation by five models with the most common output chosen as the answer","Voting does not enforce glossary terms that all versions may miss."]],
      w:"The evaluator-optimizer pattern works when there are clear criteria for quality and iteration measurably improves the result."},
    {t:"s",o:"D1.3",q:"An IT operations team wants help investigating unfamiliar production incidents. The diagnostic path depends on what each log query and probe reveals, and there is no fixed sequence of steps. Which pattern fits, and what must come with it?",
      c:["An autonomous agent with diagnostic tools, plus limits on turns and spend and approval for any changes","Correct. Open-ended, feedback-driven work suits an agent, but autonomy needs bounds and control over side effects."],
      x:[["A fixed workflow that runs the same five diagnostic queries for every incident in order","A fixed sequence cannot adapt when the next step depends on what was just found."],
         ["A single model call that reads the alert text and states the root cause directly","Without investigation tools, the model can only guess at the cause."],
         ["An autonomous agent with unrestricted permission to restart and reconfigure systems","Unbounded write access turns diagnostic mistakes into outages."]],
      w:"Agents fit open-ended tasks where the path depends on intermediate results. They need guardrails such as step and cost limits and approval for actions with side effects."},
    {t:"s",o:"D1.3",q:"A team proposes a multi-step agent framework to extract six fields (name, date, amount, account, reason, urgency) from short customer emails. What should the architect recommend?",
      c:["A single model call with the email as input and a schema-constrained output for the six fields","Correct. A bounded extraction task is well served by one augmented call with structured output."],
      x:[["Keep the agent framework, since agents are more capable than single calls for any task","More capability is not needed for a bounded extraction and adds cost, latency and failure points."],
         ["Use six separate agents, one for each field, coordinated by an orchestrator agent","Splitting a simple extraction this way multiplies calls and coordination overhead."],
         ["Use regular expressions only, since models are not reliable enough for extraction","Free-text reasons and urgency are hard to extract with patterns alone."]],
      w:"Start with the simplest pattern that meets the requirement. A single call with structured output often beats an agent for well-defined transformation tasks."},
    {t:"s",o:"D1.3",q:"A trust-and-safety team must check each uploaded document against five independent policies: privacy, copyright, violence, harassment and spam. Running the checks one after another makes review slow. Which pattern fits best?",
      c:["Parallelization: run the five policy checks at the same time and combine the results","Correct. Independent checks can run concurrently, which cuts latency and keeps each check focused."],
      x:[["Prompt chaining, where each check's output becomes the input of the next check in sequence","The checks do not depend on each other, so chaining adds latency for no benefit."],
         ["One prompt that asks the model to evaluate all five policies at once in a single response","A combined prompt tends to dilute attention across the policies and is harder to evaluate per policy."],
         ["An autonomous agent that decides which of the five policies are worth checking for each file","Every policy must be checked, so letting an agent skip some would weaken enforcement."]],
      w:"Parallelization, also called sectioning, suits independent subtasks. Running them concurrently improves speed and lets each subtask be prompted and evaluated on its own."},
    {t:"s",o:"D1.3",q:"A team wants to adopt an agent framework with memory, planning and multi-agent support for a new summarization feature. No one has yet tried a simple prompt on real examples. What is the best advice?",
      c:["Start with a simple prompt on real examples, measure it, and add complexity only when results show a need","Correct. Simple, measurable baselines prevent unnecessary complexity and show where more is truly needed."],
      x:[["Adopt the full framework now, since adding it later will cost more than starting with it","Up-front complexity is often never needed and makes the system harder to debug and operate."],
         ["Begin with a multi-agent design so the feature can scale to future requirements","Designing for hypothetical future needs adds cost now without evidence it will help."],
         ["Skip testing and launch with the framework's default settings to gather feedback quickly","Launching untested shifts the risk to users and provides no baseline to compare against."]],
      w:"Successful LLM systems usually begin with the simplest workable approach. Complexity, such as agents or orchestration, is added when measurement shows it improves results."},
    {t:"m",o:"D1.3",q:"Which TWO characteristics of a task favor a predefined workflow over an autonomous agent?",
      c:[["The steps and their order are known in advance and rarely change","Correct. Known, stable steps can be encoded directly, which is cheaper and more predictable."],
         ["The business requires predictable cost, latency and an auditable sequence of steps","Correct. Workflows give consistent behavior that is easier to audit and budget."]],
      x:[["The number of steps needed cannot be predicted before the task starts","Unpredictable step counts point toward an agent, not a fixed workflow."],
         ["The next action depends on what the previous tool call revealed","Adaptive, feedback-driven decisions are the defining strength of agents."],
         ["The task requires choosing among many tools based on changing conditions","Dynamic tool choice is better handled by an agent with guardrails."]],
      w:"Workflows suit well-defined tasks with stable steps and strict predictability needs. Agents suit open-ended problems where the path emerges during execution."},
    {t:"m",o:"D1.3",q:"Which TWO conditions make an autonomous agent a reasonable choice over a fixed workflow?",
      c:[["The path to the goal depends on intermediate results that cannot be known in advance","Correct. Agents can adapt their next step to what they observe."],
         ["The environment returns feedback, such as test results or tool output, that shows whether progress is being made","Correct. Reliable feedback lets an agent check its own progress and correct course."]],
      x:[["Regulators require the exact same sequence of steps on every run","A required fixed sequence is a reason to use a workflow."],
         ["Every response must be produced in under one second","Agent loops add turns and latency, which conflicts with very tight deadlines."],
         ["The task is a fully specified transformation of one input into one output","A fully specified transformation is best handled by a single call or simple workflow."]],
      w:"Agents are worth their cost when tasks are open-ended and the environment provides feedback; they are a poor fit for fixed, latency-critical or strictly regulated sequences."},

    // D1.4 Design multi-agent systems and orchestration strategies
    {t:"s",o:"D1.4",q:"In an orchestrator-worker research system, each worker returns the full text of every document it read. The orchestrator's context fills up after three workers and its final synthesis gets worse. What is the best fix?",
      c:["Have each worker return condensed findings with source references, not raw text","Correct. Workers should compress what they learned so the orchestrator receives signal, not bulk text."],
      x:[["Give the orchestrator a model with a larger context window so all the documents fit","A larger window postpones the problem and still buries the important findings in bulk text."],
         ["Reduce the number of workers to two so less text reaches the orchestrator","Fewer workers reduces coverage instead of fixing how results are handed back."],
         ["Have the orchestrator delete older worker results whenever its context becomes full","Dropping results loses findings that the synthesis needs."]],
      w:"A key benefit of subagents is context isolation: each works in its own context and returns a distilled result, keeping the coordinator's context focused."},
    {t:"s",o:"D1.4",q:"An orchestrator gives three research workers the instruction 'look into the market.' Two of them return nearly identical findings, and one researches the wrong region. What should change?",
      c:["Give each worker a distinct objective, scope, output format and boundaries","Correct. Clear, distinct task definitions prevent duplicated effort and gaps."],
      x:[["Add more workers so that the overlap matters less and coverage increases overall","More workers with vague instructions multiply the duplication."],
         ["Let the workers message each other freely to decide how to divide the work","Unstructured negotiation between workers adds cost and still lacks a clear plan."],
         ["Ask the orchestrator to discard duplicate findings during the final synthesis step","Discarding duplicates wastes the work already done and does not fill the gaps."]],
      w:"Orchestrators must delegate precisely: each worker needs a clear objective, scope, expected output and boundaries relative to the other workers."},
    {t:"s",o:"D1.4",q:"Two agents in a sales-operations system both update the same CRM opportunity records. Their updates sometimes overwrite each other, leaving records inconsistent. What design change addresses this?",
      c:["Give writes a single owner; the other agents only propose changes","Correct. A single writer for shared state prevents conflicting updates."],
      x:[["Tell both agents in their prompts to check the record before writing to it","Checking first does not prevent two agents from writing at nearly the same time."],
         ["Let the agent that writes most recently win, since its data is the most current","Last-write-wins silently discards valid updates from the other agent."],
         ["Run both agents more often so inconsistencies are corrected more quickly","Running more often increases the chance of conflicts rather than removing them."]],
      w:"Multi-agent systems need clear ownership of shared state. Assigning a single writer, or mediating writes through the orchestrator, avoids conflicting updates."},
    {t:"s",o:"D1.4",q:"A multi-agent research assistant spawns ten subagents for every question, including simple factual lookups such as 'What is our parental leave policy?'. Costs are far above budget. What change best aligns cost with value?",
      c:["Have the orchestrator scale the number of subagents to the complexity of each question","Correct. Effort should match the task; simple questions need one lookup, not a team of agents."],
      x:[["Always spawn exactly three subagents per question as a fixed compromise","A fixed number still over-spends on simple questions and may under-serve complex ones."],
         ["Switch every subagent to the largest model so that each one finishes sooner","Larger models raise cost per call and do not address the number of calls."],
         ["Remove the orchestrator and let the ten subagents answer in parallel","Removing coordination keeps the cost and loses the synthesis step."]],
      w:"Multi-agent systems use many more tokens than single calls. Orchestrators should scale effort to task complexity so the extra cost is spent only where it adds value."},
    {t:"s",o:"D1.4",q:"In a due-diligence system, one of four specialist agents times out while reviewing tax documents. Today the orchestrator then writes a full report anyway, filling the tax section from general knowledge. What should the orchestration do instead?",
      c:["Retry within a limit, then mark the tax section incomplete instead of filling it","Correct. Bounded retries and explicit reporting of gaps keep the output honest and reviewable."],
      x:[["Keep filling missing sections from general knowledge so the report always looks complete","Fabricating a section hides a failure in a high-stakes document."],
         ["Retry the tax agent indefinitely until it eventually succeeds","Unbounded retries can run up cost and delay the report without limit."],
         ["Abort the entire report whenever any single specialist agent fails","Aborting discards valid work from the other three specialists."]],
      w:"Orchestrators need explicit failure handling: bounded retries, partial results where appropriate, and clear reporting of what is missing."},
    {t:"m",o:"D1.4",q:"Auditors must be able to verify how a multi-agent system reached a recommendation. Which TWO practices best support this?",
      c:[["Carry source references through every handoff so final claims can be traced to evidence","Correct. Traceable sources let reviewers check each claim back to its origin."],
         ["Log each agent's inputs, outputs and tool calls under a shared trace ID","Correct. Linked logs show which agent did what and in what order."]],
      x:[["Let the final agent rewrite the findings in its own words without keeping sources","Rewriting without sources breaks the chain from claim to evidence."],
         ["Use one shared scratchpad that every agent edits without attribution","Unattributed shared edits make it impossible to tell which agent contributed what."],
         ["Turn off subagent logging to reduce storage costs","Missing subagent logs leave the most detailed part of the process unrecorded."]],
      w:"Auditability in multi-agent systems depends on provenance that survives handoffs and on correlated logs for each agent's work."},
    {t:"m",o:"D1.4",q:"A multi-agent system occasionally runs away, spawning subagents that spawn more subagents and running for hours. Which TWO controls best prevent this?",
      c:[["Set hard limits on subagent depth, total subagents and turns or spend per run","Correct. Explicit budgets stop runaway recursion and cost."],
         ["Have the orchestrator decide how many subagents to create based on task complexity","Correct. Central, complexity-based planning prevents unnecessary fan-out."]],
      x:[["Allow unlimited retries so that subagents can recover from any error on their own","Unlimited retries are a common cause of runaway runs."],
         ["Give every subagent the full tool set so it never needs to delegate further","Broad tools increase risk and do not limit recursion."],
         ["Let any subagent create its own subagents whenever it judges the task is large","Unrestricted delegation is exactly what causes the runaway behavior."]],
      w:"Multi-agent orchestration needs budgets and central control over delegation, so effort stays proportional to the task."},
    {t:"c",o:"D1.4",q:"An architecture team is choosing orchestration for five workloads. For each, choose the pattern that fits best. Options may be reused.",
      opts:["Prompt chaining","Routing","Parallelization","Orchestrator-workers","Evaluator-optimizer"],
      rows:[["Write an outline, check it against requirements, then draft the document from the approved outline",0,"Fixed sequential steps, each using the previous output, are prompt chaining."],
            ["Send billing, technical and sales questions to different specialized handlers",1,"Classifying inputs and directing them to specialized handling is routing."],
            ["Review one contract against five independent policy checks at the same time",2,"Independent checks run concurrently are parallelization."],
            ["Research a question whose subtopics are not known until the first search results arrive",3,"Dynamic decomposition by a coordinator suits orchestrator-workers."],
            ["Revise a translation repeatedly against a style rubric until it passes",4,"A generate-critique-revise loop with clear criteria is evaluator-optimizer."]],
      w:"Each orchestration pattern fits a different structure: fixed sequences, categorized inputs, independent subtasks, unknown decompositions or iterative refinement."},

    // D1.5 Apply decomposition techniques for complex problem solving
    {t:"s",o:"D1.5",q:"A single prompt asked to 'write our 60-page annual sustainability report' produces inconsistent sections, repeated content and missed data. What decomposition works best?",
      c:["Split it into sections with clear inputs and outputs, then check consistency","Correct. Section-level tasks with clear contracts, followed by an integration check, make long outputs manageable."],
      x:[["Raise the maximum output length so the full report fits in one response","A longer single response does not fix inconsistency or missing data."],
         ["Ask the model to write the report twice and keep the version that looks better","Repeating the same oversized task does not address why it fails."],
         ["Split the report into 60 one-page chunks and generate each page independently","Page boundaries are arbitrary and break sections apart, worsening consistency."]],
      w:"Decomposition should follow the natural structure of the work, with clear inputs and outputs per part and a final integration step to check consistency."},
    {t:"s",o:"D1.5",q:"A team decomposes a vendor-risk assessment either by data source (financials, news, security questionnaires) or by deliverable section (summary, risks, recommendation). Each source feeds several sections. Which principle should guide the choice?",
      c:["Pick the split that keeps subtasks most independent of each other","Correct. Minimizing dependencies between subtasks reduces coordination and error propagation."],
      x:[["Always split by deliverable section, since that matches what readers will see","Matching the reader's view does not help if each section needs every data source."],
         ["Always split by data source, since that is how the information arrives","Arrival format alone does not guarantee independent, well-bounded subtasks."],
         ["Create as many subtasks as possible, since more parts always means better results","More parts add coordination overhead and more places for errors."]],
      w:"Good decompositions minimize coupling: each subtask should be completable with little dependence on the others' intermediate state."},
    {t:"s",o:"D1.5",q:"An extraction pipeline pulls 25 fields from loan applications. Errors are rare but costly, and reviewers cannot tell which fields to double-check. Which decomposition adds the most value?",
      c:["Add a step that checks each field against the source and flags mismatches","Correct. A dedicated verification pass makes errors visible and tells reviewers where to look."],
      x:[["Extract the 25 fields twice with the same prompt and keep the first result","Repeating the same step adds cost without independent checking."],
         ["Ask the model to report its confidence for the whole application in one number","A single score does not show which fields need attention."],
         ["Remove the least important fields so there are fewer chances to make mistakes","Dropping required fields does not solve accuracy for the remaining ones."]],
      w:"Decomposing work into generation and verification steps is a common way to catch errors and target human review where it matters."},
    {t:"s",o:"D1.5",q:"A complex compliance question is answered by one large prompt that classifies the question, retrieves policy text and writes the answer. When answers are wrong, the team cannot tell which part failed. What decomposition helps most?",
      c:["Split it into classify, retrieve, answer and cite-check steps, each tested","Correct. Separate, testable steps show where failures happen and allow targeted fixes."],
      x:[["Add more instructions to the single prompt about being careful with compliance answers","More instructions do not make the failure location any easier to see."],
         ["Use a more capable model so the single prompt fails less often overall","Fewer failures may help, but they would still be impossible to diagnose."],
         ["Ask users to rephrase their questions whenever an answer looks wrong to them","Shifting the burden to users does not improve the system's diagnosability."]],
      w:"Decomposition makes systems testable: each step has a defined output that can be evaluated, so failures can be located and fixed."},
    {t:"s",o:"D1.5",q:"A simple email-reply task was split into 12 micro-steps, each a separate model call. Latency is now 18 seconds and small errors compound from step to step. What should the architect recommend?",
      c:["Merge steps one call handles well; keep only steps that add value","Correct. Over-decomposition adds latency and error propagation; steps should exist only when they help."],
      x:[["Add a 13th step that reviews and corrects the output of the previous 12","Another step adds more latency and does not remove the compounding errors."],
         ["Run all 12 steps in parallel to bring the total latency down","The steps depend on each other, so they cannot simply run in parallel."],
         ["Switch every step to the smallest model so each call returns faster","Weaker models may increase the errors that already compound between steps."]],
      w:"Decomposition has costs. Each extra step adds latency and a chance of error, so the number of steps should be justified by evaluation results."},
    {t:"s",o:"D1.5",q:"In a three-stage pipeline (extract facts → analyze risks → draft memo), the drafting stage sometimes misreads the analysis stage's free-text notes. What change makes the stages more reliable?",
      c:["Define structured outputs between stages, such as a schema for the risk analysis","Correct. Explicit contracts between stages reduce misinterpretation and make failures easy to localize."],
      x:[["Merge the three stages back into a single prompt to avoid any handoffs","Merging loses the testability and focus that the stages provide."],
         ["Ask the drafting stage to guess what the analysis stage meant when notes are unclear","Guessing turns ambiguity into silent errors."],
         ["Pass the entire conversation history of each stage to the next one","More raw text adds noise rather than a clear, checkable interface."]],
      w:"Decomposed pipelines need clear interfaces. Structured intermediate outputs act as contracts that each stage can rely on and that tests can check."},
    {t:"m",o:"D1.5",q:"Which TWO are real benefits of decomposing a complex document-review task into stages?",
      c:[["Each stage can be evaluated and improved separately","Correct. Stage-level evaluation shows where quality problems come from."],
         ["Each stage can use a model suited to its difficulty, such as a smaller model for classification","Correct. Matching model tier to stage difficulty can lower cost without hurting quality."]],
      x:[["It removes the need to evaluate the end-to-end result","End-to-end evaluation is still needed to confirm the stages work together."],
         ["It guarantees lower total latency than a single call","More stages often add latency; the benefit is control and quality, not guaranteed speed."],
         ["It removes the need for human review of high-impact outputs","Decomposition does not change the need for oversight on consequential decisions."]],
      w:"Decomposition adds testability and flexibility in model choice, but it does not remove the need for end-to-end evaluation or human oversight."},
    {t:"m",o:"D1.5",q:"Which TWO signs indicate that a problem has been decomposed poorly?",
      c:[["Subtasks constantly need each other's intermediate state to make progress","Correct. Heavy coupling means the boundaries were drawn in the wrong place."],
         ["Errors from early stages reach the final output because no stage checks its inputs","Correct. Without checks at the boundaries, errors propagate silently."]],
      x:[["Each subtask has a clear input and a clear expected output","Clear interfaces are a sign of a good decomposition."],
         ["Several subtasks can run in parallel without waiting for each other","Independence between subtasks is a benefit of good decomposition."],
         ["Each stage has its own small test set","Stage-level tests are a strength, not a warning sign."]],
      w:"Poor decompositions show up as tight coupling between parts and as errors passing unchecked between stages."},
    {t:"c",o:"D1.5",q:"A team is planning how to break down five problems. For each, choose the decomposition approach that fits best. Options may be reused.",
      opts:["Sequential stages, each using the previous output","Independent subtasks that can run in parallel","Separate the exact rule-based work from the language work"],
      rows:[["Check that a purchase order's total equals the sum of its lines, then write the supplier email",2,"Exact arithmetic belongs in code; the email is language work."],
            ["Review 40 vendor contracts for the same indemnity clause",1,"Each contract can be reviewed independently and concurrently."],
            ["Extract facts from a case file, then draft a memo using only those extracted facts",0,"The memo depends on the extraction, so the steps are sequential."],
            ["Translate a product manual into six languages",1,"Each translation is independent of the others."],
            ["Apply a fixed refund-eligibility rule, then explain the outcome to the customer in plain language",2,"The rule should be applied exactly in code; Claude explains the result."]],
      w:"Decomposition techniques include sequencing dependent steps, parallelizing independent ones, and separating deterministic logic from language tasks."},

    // D1.6 Align solutions to business value pillars
    {t:"s",o:"D1.6",q:"A Claude-based proposal assistant cuts first-draft time from three days to four hours. How should the team report this value to the sponsor?",
      c:["As productivity: time saved and output per person, with a quality check","Correct. Time saved and throughput, backed by a quality check, show productivity value credibly."],
      x:[["As the total number of tokens the assistant processed during the quarter","Token volume measures activity, not business value."],
         ["As the model's score on a public writing benchmark that the team ran","Benchmarks do not show what changed for this business."],
         ["As the number of prompts the team wrote while building the assistant","Prompt counts describe effort, not outcomes."]],
      w:"Value should be reported in the business pillar it affects, using outcome metrics against a baseline, such as time per unit and throughput for productivity."},
    {t:"s",o:"D1.6",q:"An insurer launches instant, 24/7 policy explanations for customers, a service it never offered before. Which value pillar does this mainly represent, and how should it be measured?",
      c:["Transformation: track adoption, questions resolved and customer impact","Correct. A new capability is a transformation outcome, measured by use and its business effect."],
      x:[["Cost reduction: measure the decrease in the call center's monthly spend","The service is new, so there is no existing cost line it directly reduces."],
         ["Efficiency: measure how many tokens each explanation uses on average","Token use is a cost driver, not a measure of the new capability's value."],
         ["Performance SLA: measure only the p95 response time of the new service","Latency matters, but it does not capture the value of the new capability."]],
      w:"Transformation means enabling something new. Its value shows up in adoption and in business outcomes the new capability affects."},
    {t:"s",o:"D1.6",q:"A customer-facing assistant has a contractual SLA of 99.9% availability and a 2-second p95 response time. Which design decision is justified mainly by the performance-SLA pillar?",
      c:["Fallbacks such as cached answers or human handoff during outages","Correct. Fallbacks protect availability and response-time commitments when a dependency degrades."],
      x:[["A larger system prompt with more detailed instructions for every answer","More instructions affect behavior, not availability or latency guarantees."],
         ["Monthly reports of total token spend broken down by product line","Spend reporting supports the cost pillar, not the SLA."],
         ["A thumbs-up and thumbs-down button on every answer for user feedback","Feedback improves quality over time but does not protect the SLA."]],
      w:"The performance pillar covers latency, throughput and availability commitments. Designs such as fallbacks and graceful degradation are justified by those SLAs."},
    {t:"s",o:"D1.6",q:"A CFO is the main decision maker for expanding an AI service, and she cares most about operating margin. How should the architect frame the business case?",
      c:["Lead with cost and efficiency tied to the P&L, against today's baseline","Correct. Framing value in the decision maker's terms, with a baseline, makes the case relevant and credible."],
      x:[["Lead with the model's technical capabilities and recent benchmark results","Capabilities are not the outcome a margin-focused CFO is evaluating."],
         ["Lead with the number of employees who have tried the assistant so far","Trial counts show interest, not financial impact."],
         ["Lead with the long-term vision of an AI-first company in five years","A distant vision does not answer the CFO's question about margin now."]],
      w:"Aligning to value pillars includes choosing the pillar that matters to the audience and expressing it in their metrics."},
    {t:"s",o:"D1.6",q:"Before launching a claims-summarization assistant, the team wants a measurement plan that will show value within two quarters. Which plan is strongest?",
      c:["Baseline handling time and errors now, then track adoption and outcomes","Correct. A baseline plus leading and lagging indicators shows both early progress and real impact."],
      x:[["Wait until the end of the second quarter and survey adjusters about whether they like it","A late, unbaselined survey cannot show measurable change."],
         ["Track only the number of summaries generated each day after launch","Volume shows usage, not whether handling time or quality improved."],
         ["Compare the assistant's accuracy with a different company's published case study","Another company's results are not evidence for this deployment."]],
      w:"Value measurement needs a pre-launch baseline, leading indicators such as adoption, and lagging outcome metrics such as handling time and error rate."},
    {t:"s",o:"D1.6",q:"Switching all traffic to a cheaper model would cut costs by 40%, but evaluations show quality would fall below the SLA for a premium customer tier that is 10% of traffic. What should the architect recommend?",
      c:["Route premium traffic to the stronger model, the rest to the cheaper one","Correct. Segment-based routing captures most of the savings while protecting the SLA, and the trade-off is made explicit."],
      x:[["Switch everything to the cheaper model, since cost savings matter most to the business","Breaking a premium SLA can cost more in churn and penalties than the savings."],
         ["Keep everything on the stronger model, since quality should never be traded for cost","Refusing any trade-off ignores large savings available for most traffic."],
         ["Switch everything and handle premium complaints as they arrive","Reacting to complaints accepts SLA breaches that were predicted in advance."]],
      w:"Value pillars can conflict. The architect quantifies the trade-off and often resolves it by segmenting, so cost savings do not come at the expense of SLA commitments."},
    {t:"m",o:"D1.6",q:"Which TWO measures belong to the performance-SLA pillar for a customer-facing assistant?",
      c:[["p95 response time measured against the agreed target","Correct. Tail latency is a core performance commitment."],
         ["Availability, with defined behavior when the model service degrades","Correct. Uptime and graceful degradation are part of performance commitments."]],
      x:[["Total tokens processed per month","Token volume relates to cost, not to service-level performance."],
         ["Number of prompt templates in the library","Template counts describe implementation effort, not service levels."],
         ["Number of tools the assistant can call","Tool count is an implementation detail, not an SLA measure."]],
      w:"Performance SLAs are expressed in latency, throughput and availability, with defined behavior when dependencies degrade."},
    {t:"c",o:"D1.6",q:"For each outcome, choose the value pillar it mainly represents. Options may be reused.",
      opts:["Cost reduction","Productivity","Transformation","Performance SLA"],
      rows:[["Monthly document-processing spend falls from $90,000 to $35,000",0,"A lower spend for the same work is cost reduction."],
            ["Each analyst completes three times as many vendor reviews per week",1,"More output per person is productivity."],
            ["Customers get instant policy answers around the clock, a service that did not exist before",2,"A new capability is transformation."],
            ["p95 response time stays under 2 seconds at peak traffic",3,"A latency commitment is a performance SLA."],
            ["Cost per resolved support ticket drops by 30%",0,"A lower unit cost is cost reduction."]],
      w:"Mapping outcomes to value pillars helps the team choose the right metrics and explain value to each stakeholder."},
  ];
})();
